import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"ush — the complete shell reference","description":"","frontmatter":{},"headers":[],"relativePath":"manual/ush-reference.md","filePath":"manual/ush-reference.md"}'),a={name:"manual/ush-reference.md"};function s(c,e,n,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="ush-—-the-complete-shell-reference" tabindex="-1">ush — the complete shell reference <a class="header-anchor" href="#ush-—-the-complete-shell-reference" aria-label="Permalink to &quot;ush — the complete shell reference&quot;">​</a></h1><p><code>ush</code> is the ring-3 shell and the default boot entry (the kernel&#39;s <code>l1_launcher_boot_default()</code> spawns it; when it exits, L0 halts). It lives at <code>ocos/l1apps/ush/main.c</code> — a raw ELF (the only non-gzipped registry program), using SYS_READLINE(73)/SYS_GETCH(74) for input, fork+execve+wait4 for programs, SYS_PIPE(20)+SYS_DUP2(51) for pipes, SYS_OPEN/CLOSE for redirection.</p><h2 id="the-12-built-ins" tabindex="-1">The 12 built-ins <a class="header-anchor" href="#the-12-built-ins" aria-label="Permalink to &quot;The 12 built-ins&quot;">​</a></h2><p>Only these twelve words are interpreted by the shell itself. Everything else is a registry program.</p><table tabindex="0"><thead><tr><th>Built-in</th><th>Syntax</th><th>Behavior</th></tr></thead><tbody><tr><td><code>cd</code></td><td><code>cd [dir]</code></td><td>change the shell&#39;s working directory; no argument = <code>/</code></td></tr><tr><td><code>help</code></td><td><code>help [-a|-w]</code></td><td>built-in summary + registry count line; <code>-a</code>/<code>--all</code> = full A-Z listing, <code>-w</code>/<code>--wp</code> = grouped by work package (mega group first)</td></tr><tr><td><code>export</code></td><td><code>export VAR=val</code></td><td>set an environment variable (32 vars max, name ≤ 32, value ≤ 128 bytes)</td></tr><tr><td><code>alias</code></td><td><code>alias name=val</code> / <code>alias name value...</code></td><td>set an alias (16 max, name ≤ 32, value ≤ 64); bare <code>alias</code> lists all; <code>alias name</code> prints one</td></tr><tr><td><code>unalias</code></td><td><code>unalias name</code></td><td>remove an alias; prints a usage error when called without an argument</td></tr><tr><td><code>env</code></td><td><code>env</code></td><td>print all environment variables</td></tr><tr><td><code>set</code></td><td><code>set [VAR]</code></td><td>bare <code>set</code> shows variables; <code>set VAR</code> prints <code>VAR=value</code></td></tr><tr><td><code>history</code></td><td><code>history</code></td><td>numbered history, 1..n</td></tr><tr><td><code>jobs</code></td><td><code>jobs</code></td><td>list background job table entries</td></tr><tr><td><code>fg</code></td><td><code>fg [job]</code></td><td><strong>not available</strong> — prints <code>ush: job control requires external programs</code></td></tr><tr><td><code>bg</code></td><td><code>bg</code></td><td><strong>not available</strong> — same message</td></tr><tr><td><code>exit</code></td><td><code>exit</code></td><td><strong>refused</strong> — <code>ush: &#39;exit&#39; is not available; use &#39;shutdown&#39; to power off, &#39;reboot&#39; to restart</code></td></tr></tbody></table><p>Notes:</p><ul><li><code>fg</code>/<code>bg</code> are recognized words but job <strong>resume</strong> is not implemented. <code>jobs</code> listing and <code>cmd &amp;</code> background launch ARE real (16 job slots; the parent prints <code>[n] &lt;pid&gt;</code>).</li><li><code>exit</code> refuses because there is nothing to exit to — ush IS the boot entry; its exit is end-of-session (the kernel prints <code>l1 launcher: default L1 app exited; L0 halting</code>).</li><li>The words that used to be built-ins in v2.x (<code>ls</code>, <code>cat</code>, <code>wc</code>, <code>grep</code>, <code>head</code>, <code>tail</code>, <code>mkdir</code>, <code>rmdir</code>, <code>touch</code>, <code>rm</code>, <code>cp</code>, <code>mv</code>, <code>sort</code>, <code>uniq</code>, <code>ps</code>, <code>top</code>, <code>kill</code>, <code>date</code>, <code>uname</code>, <code>free</code>, <code>df</code>, <code>stat</code>, <code>du</code>, <code>ln</code>, <code>chmod</code>, <code>chown</code>, <code>sed</code>, <code>awk</code>, <code>ping</code>, <code>wget</code>, <code>netstat</code>, <code>ifconfig</code>, <code>nano</code>/<code>vi</code>/<code>edit</code>) are now ordinary apps reached via execve.</li></ul><h2 id="the-line-editor" tabindex="-1">The line editor <a class="header-anchor" href="#the-line-editor" aria-label="Permalink to &quot;The line editor&quot;">​</a></h2><p>All editing happens on raw SYS_GETCH codes; the line cap is 511 bytes.</p><table tabindex="0"><thead><tr><th>Key</th><th>Code</th><th>Action</th></tr></thead><tbody><tr><td>Up</td><td>0x80</td><td>previous history entry (draft preserved — see below)</td></tr><tr><td>Down</td><td>0x81</td><td>next history entry; past the newest restores your draft</td></tr><tr><td>Left / Right</td><td>0x82 / 0x83</td><td>glyph-wise cursor motion (UTF-8 aware: <code>u8_prev</code>/<code>u8_next</code>)</td></tr><tr><td>Home / Ctrl+A</td><td>0x84 / 0x01</td><td>line start</td></tr><tr><td>End / Ctrl+E</td><td>0x85 / 0x05</td><td>line end</td></tr><tr><td>Delete</td><td>0x89</td><td>delete glyph at cursor</td></tr><tr><td>Backspace</td><td>0x08 / 0x7F</td><td>delete glyph before cursor</td></tr><tr><td>Ctrl+U</td><td>0x15</td><td>kill to line start</td></tr><tr><td>Ctrl+K</td><td>0x0B</td><td>kill to line end</td></tr><tr><td>Ctrl+W</td><td>0x17</td><td>kill previous word</td></tr><tr><td>Ctrl+C</td><td>0x03</td><td><code>^C</code> — cancel the line</td></tr><tr><td>Tab</td><td>0x09</td><td>completion (see below)</td></tr><tr><td>0x100..0x1FF</td><td>—</td><td>serial-pasted UTF-8 bytes: the COM1 bridge&#39;s +0x100 bias is stripped, so pasted CJK accumulates byte-by-byte</td></tr><tr><td>printable ASCII</td><td>—</td><td>insert at cursor</td></tr></tbody></table><p><strong>History</strong>: 16 entries, 256 bytes each, consecutive duplicates deduplicated, FIFO slide when full. <code>history</code> prints them numbered.</p><h2 id="tab-completion-—-registry-driven" tabindex="-1">Tab completion — registry-driven <a class="header-anchor" href="#tab-completion-—-registry-driven" aria-label="Permalink to &quot;Tab completion — registry-driven&quot;">​</a></h2><p>Candidates are the <strong>live registry</strong> — the exact text <code>help</code> prints, fetched through the L1SVC <code>l1/apps</code> op (footer <code>--</code> lines skipped, cap 290 entries) — plus the 12 true built-ins.</p><ul><li>Single match: completes the word and appends a space.</li><li>Multiple matches: completes the common prefix.</li><li>No command match and the word contains <code>/</code> (or is any later word on the line): <strong>VFS filename completion</strong> kicks in — the directory part is read via sys_readdir (64 entries scanned, common-prefix logic, bounded appends).</li></ul><p>Completion never enumerates command <em>arguments</em> — subcommand grammars are documented in <a href="./function-dictionary.html">function-dictionary.md</a>.</p><h2 id="pipes-redirection-background" tabindex="-1">Pipes, redirection, background <a class="header-anchor" href="#pipes-redirection-background" aria-label="Permalink to &quot;Pipes, redirection, background&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Syntax</th><th>Limits</th></tr></thead><tbody><tr><td>Pipeline</td><td><code>cmd1 | cmd2 | ...</code></td><td>max <strong>8 segments</strong>; pipes created up front, one fork per segment; the first child keeps console stdin, the last keeps console stdout</td></tr><tr><td>Redirect out</td><td><code>cmd &gt; file</code> (truncate), <code>cmd &gt;&gt; file</code> (append)</td><td>parsed anywhere in the command; originals dup()&#39;d and restored; built-ins DO see redirects</td></tr><tr><td>Redirect in</td><td><code>cmd &lt; file</code></td><td>same mechanism over fd 0</td></tr><tr><td>Background</td><td><code>cmd &amp;</code></td><td>fork without wait; job table entry; prints <code>[n] &lt;pid&gt;</code></td></tr></tbody></table><p>An empty redirect target is a syntax error: <code>ush: syntax error near &#39;&gt;&#39; </code> (and <code>near &#39;&lt;&#39;</code>).</p><h2 id="variable-substitution-—-and-what-ush-does-not-have" tabindex="-1">Variable substitution — and what ush does NOT have <a class="header-anchor" href="#variable-substitution-—-and-what-ush-does-not-have" aria-label="Permalink to &quot;Variable substitution — and what ush does NOT have&quot;">​</a></h2><p><code>$VAR</code> expansion is the <strong>only</strong> substitution (<code>expand_env</code>, 512-byte result; <code>echo $PATH</code>, <code>export X=...; run echo $X</code> work).</p><p>The shell deliberately does <strong>not</strong> implement:</p><ul><li><strong>wildcards/globbing</strong> — <code>ls *</code> passes the literal <code>*</code> to <code>ls</code>, which also has no glob. No <code>?</code>, no <code>[...]</code> anywhere.</li><li><code>&amp;&amp;</code> / <code>||</code> chaining</li><li><code>$?</code> and any other special variables</li><li>quoting (no <code>&#39;...&#39;</code> / <code>&quot;...&quot;</code>)</li><li>heredocs</li><li>functions, arithmetic, loops — scripting is one command per line</li></ul><p>Commands not found print <code>ush: command not found: &lt;cmd&gt;</code>; fork failures print <code>ush: fork failed</code>; alias expansion that overflows prints <code>ush: alias expansion too long</code>.</p><hr><h2 id="the-editors" tabindex="-1">The editors <a class="header-anchor" href="#the-editors" aria-label="Permalink to &quot;The editors&quot;">​</a></h2><p>One shared engine (<code>ocos/interface/editor_core.h</code>), three faces: <strong>nano</strong> and <strong>edit</strong> are byte-for-byte the same nano-style face (edit is the v2.2.0 spelling); <strong>vi</strong> is a real modal layer over the same engine. Limits: 256 lines × 128 bytes/line; a file past the limits loads partially (<code>unano_file_truncated</code> / <code>partial load</code>) and <strong>save refuses to overwrite</strong> — the status bar shows <code>[PARTIAL: save refused]</code>.</p><h3 id="nano-edit-keys" tabindex="-1">nano / edit keys <a class="header-anchor" href="#nano-edit-keys" aria-label="Permalink to &quot;nano / edit keys&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td>arrows</td><td>glyph-wise motion</td></tr><tr><td>typing</td><td>inserts UTF-8</td></tr><tr><td>Backspace / Delete</td><td>remove whole glyphs</td></tr><tr><td>ENTER</td><td>split the line</td></tr><tr><td><strong>F2</strong></td><td>toggle the <strong>system IME</strong> (pinyin; the engine lives in the L0 display service — the editor only toggles + feeds keys + renders the preedit strip). While composing: digits 1-9 pick a candidate, space = first, PgUp/PgDn or <code>-</code>/<code>=</code> page, Backspace drops a letter, Enter commits the raw letters, Esc cancels</td></tr><tr><td>Ctrl+K (0x0B)</td><td>cut line</td></tr><tr><td>Ctrl+R (0x12)</td><td>copy line</td></tr><tr><td>Ctrl+U (0x15)</td><td>paste the clipboard line below (UTF-8-safe, one-line clipboard)</td></tr><tr><td>Ctrl+C (0x03)</td><td>report cursor position</td></tr><tr><td>Ctrl+O (0x0F)</td><td>save</td></tr><tr><td>Ctrl+X (0x18)</td><td>exit (asks when dirty)</td></tr><tr><td>Ctrl+G</td><td>help</td></tr></tbody></table><p>The status bar is a differential pinned bottom row (ANSI <code>\\033[s\\033[999;1H\\033[K...\\033[u</code>; zero output when unchanged): <code>[* ]file 1/3 IME:on [preedit]</code>.</p><h3 id="vi-keys" tabindex="-1">vi keys <a class="header-anchor" href="#vi-keys" aria-label="Permalink to &quot;vi keys&quot;">​</a></h3><p>COMMAND mode (default):</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>h j k l</code> / arrows</td><td>motion (h/l glyph-wise)</td></tr><tr><td><code>0</code> / <code>$</code></td><td>line start / end</td></tr><tr><td><code>x</code></td><td>delete glyph at cursor</td></tr><tr><td><code>dd</code></td><td>cut line</td></tr><tr><td><code>yy</code></td><td>copy line</td></tr><tr><td><code>p</code></td><td>paste below</td></tr><tr><td><code>i</code> / <code>a</code> / <code>o</code></td><td>enter INSERT (at cursor / after it / new line below)</td></tr><tr><td><code>:</code></td><td>ex line: <code>:w</code> save, <code>:q</code> quit, <code>:wq</code> both, <code>:q!</code> discard</td></tr></tbody></table><p>INSERT mode: typing inserts (UTF-8 glyph-aware), Backspace/Delete remove whole glyphs, <strong>F2 toggles the system IME</strong> (same engine as nano), <code>Esc</code> returns to COMMAND. Status bar: <code>[* ]file 1/3 CMD|INSERT</code></p><ul><li>preedit strip.</li></ul><hr><h2 id="the-tui-family-and-its-hotkeys" tabindex="-1">The TUI family and its hotkeys <a class="header-anchor" href="#the-tui-family-and-its-hotkeys" aria-label="Permalink to &quot;The TUI family and its hotkeys&quot;">​</a></h2><p><code>tui</code> (desktop) and the seven page apps (<code>tui-sys</code>, <code>tui-sysinfo</code>, <code>tui-hw</code>, <code>tui-drv</code>, <code>tui-net</code>, <code>tui-time</code>, <code>tui-ext</code>) render full-screen and bypass the text capture (their output never reaches an L1SVC capture buffer). <code>tui-test</code> serves its verdict through the capture. All pages share one key loop:</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>next page (tab bar shows <code>[current]</code>)</td></tr><tr><td><code>Up</code> / <code>Down</code></td><td>scroll the page (long pages such as PCI caps can be read past the first screen)</td></tr><tr><td><code>+</code> / <code>=</code></td><td>volume +10 (Sound page; persists <code>snd.volume</code> to config)</td></tr><tr><td><code>-</code></td><td>volume -10</td></tr><tr><td><code>F1</code></td><td>help (the shared sysinfo help screen)</td></tr><tr><td><code>F2</code></td><td>save config (<code>/etc/opencube.conf</code> or defaults)</td></tr><tr><td><code>F5</code></td><td>repaint</td></tr><tr><td><code>Esc</code> / <code>F10</code> / <code>q</code></td><td>leave the page, back to the prompt</td></tr></tbody></table><h2 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; help -w                          # find commands by group</span></span>
<span class="line"><span>ush&gt; top -n 5                         # five refreshes, then exits</span></span>
<span class="line"><span>ush&gt; cat /etc/opencube.conf           # no pager; pipe into head</span></span>
<span class="line"><span>ush&gt; dmesg 100 &gt; /tmp/boot.txt        # capture the last 100 klog lines</span></span>
<span class="line"><span>ush&gt; grep dhcp &lt; /tmp/boot.txt        # grep filters stdin</span></span>
<span class="line"><span>ush&gt; play 440 &amp;                       # background job: [1] 12</span></span>
<span class="line"><span>ush&gt; jobs                             # see it</span></span>
<span class="line"><span>ush&gt; ime -i                           # interactive pinyin compose line</span></span></code></pre></div><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./function-dictionary.html">function-dictionary.md</a> — all 311 commands</li><li><a href="./shell-basics.html">shell-basics.md</a> — the beginner&#39;s tour</li><li><a href="./getting-started.html">getting-started.md</a> — first boot</li><li><a href="./../troubleshooting/silent-failures.html">../troubleshooting/silent-failures.md</a> — why some console output never appears (capture routing)</li></ul>`,42)])])}const g=t(a,[["render",s]]);export{u as __pageData,g as default};
